DROP TABLE IF EXISTS `log_operate`;
CREATE TABLE `log_operate`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `module_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '模块名称',
  `oper_addr` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '操作地点',
  `oper_ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '主机地址',
  `oper_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '请求URL',
  `oper_agent` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '请求浏览器',
  `oper_param` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL COMMENT '请求参数',
  `oper_type` int NULL DEFAULT 0 COMMENT '操作类别',
  `login_type` int NULL DEFAULT 0 COMMENT '登录类型',
  `method_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '方法名称',
  `method_request` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '请求方式',
  `result_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '0' COMMENT '操作状态',
  `result_msg` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL COMMENT '错误消息',
  `result_data` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL COMMENT '返回参数',
  `create_user_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT '' COMMENT '操作人员',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `scope_user_id` bigint NULL DEFAULT NULL COMMENT '数据权限用户ID',
  `scope_org_id` bigint NULL DEFAULT NULL COMMENT '数据权限层级ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2096853356075724803 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '操作日志' ROW_FORMAT = DYNAMIC;

