-- ----------------------------
-- Table structure for sys_account
-- ----------------------------
DROP TABLE IF EXISTS `sys_account`;
CREATE TABLE `sys_account`  (
  `account_id` bigint NOT NULL AUTO_INCREMENT COMMENT '帐户ID',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户ID',
  `third_user_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方用户ID',
  `third_union_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方唯一ID',
  `account_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账号码',
  `check_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '校验码',
  `nick_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户昵称',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '头像地址',
  `source_flag` tinyint(1) NULL DEFAULT 0 COMMENT '用户类型（SourceFlagEnum）',
  `account_flag` tinyint(1) NULL DEFAULT NULL COMMENT '帐号状态（AccountFlagEnum）',
  `preview_flag` tinyint(1) NULL DEFAULT NULL COMMENT '预览模式（YesOrNoEnum）',
  `del_flag` tinyint(1) NULL DEFAULT 0 COMMENT '删除标志（YesOrNoEnum）',
  `login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后登陆IP',
  `login_time` datetime NULL DEFAULT NULL COMMENT '最后登陆时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `scope_root_id` bigint NULL DEFAULT NULL COMMENT '账户所属当前根组织',
  `scope_org_id` bigint NULL DEFAULT NULL COMMENT '账户所属当前组织',
  PRIMARY KEY (`account_id`) USING BTREE,
  INDEX `USER_ID`(`user_id` ASC) USING BTREE COMMENT '人员ID'
) ENGINE = InnoDB AUTO_INCREMENT = 2093154639497879555 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统账户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_account
-- ----------------------------

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '菜单自增ID',
  `root_id` bigint NULL DEFAULT NULL COMMENT '根ID',
  `parent_id` bigint NOT NULL COMMENT '父菜单ID',
  `module_id` bigint NULL DEFAULT NULL COMMENT '模块id(非必填， 有的手动创建的不需要传入模块id)',
  `arg_type` tinyint(1) NULL DEFAULT NULL COMMENT '路由参数类型(Item,Mate)',
  `menu_type` tinyint(1) NULL DEFAULT NULL COMMENT '菜单类型(MenuTypeEnum)',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '命名路由',
  `alias` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '别名',
  `mac` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '编码标识',
  `component` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '命名视图组件',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '路径',
  `redirect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '重定向路径',
  `case_sensitive` tinyint(1) NULL DEFAULT NULL COMMENT '匹配规则是否大小写敏感',
  `order_no` int NULL DEFAULT NULL COMMENT '路由顺序，可用于菜单的排序',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '路由标题',
  `href` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '外链链接',
  `icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '菜单和面包屑对应的图标',
  `icon_m` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '菜单和面包屑对应的图标2',
  `icon_l` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '菜单和面包屑对应的图标3',
  `single_layout` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '作为单级路由的父级路由布局组件',
  `dynamic_path` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '路由的动态路径',
  `active_menu` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '当前路由需要选中的菜单项(用于跳转至不在左侧菜单显示的路由且需要高亮某个菜单的情况)',
  `params` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '路由参数',
  `permissions` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '哪些类型的用户有权限才能访问的路由',
  `requires_auth` tinyint(1) NULL DEFAULT NULL COMMENT '需要登录权限',
  `affix` tinyint(1) NULL DEFAULT NULL COMMENT '是否固定在tab卡不可关闭',
  `multi` tinyint(1) NULL DEFAULT NULL COMMENT '表示是否是多级路由的中间级路由(用于转换路由数据时筛选多级路由的标识，定义路由时不用填写)',
  `multi_tab` tinyint(1) NULL DEFAULT NULL COMMENT '是否支持多个tab页签(默认一个，即相同name的路由会被替换)',
  `keep_alive` tinyint(1) NULL DEFAULT NULL COMMENT '缓存页面',
  `hide_menu` tinyint(1) NULL DEFAULT NULL COMMENT '是否在菜单中隐藏(一些列表、表格的详情页面需要通过参数跳转，所以不能显示在菜单中)',
  `hide_menu_children` tinyint(1) NULL DEFAULT NULL COMMENT '是否隐藏菜单子项',
  `always_show` tinyint(1) NULL DEFAULT NULL COMMENT '是否总是显示',
  `del_flag` int NULL DEFAULT 1 COMMENT '删除标识',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2086738252952940546 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '系统菜单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_menu
-- ----------------------------

-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '角色自增ID',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '角色父ID',
  `role_name` varchar(16) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '角色名',
  `act_flag` tinyint(1) NULL DEFAULT NULL COMMENT '激活状态(YesOrNoEnum)',
  `del_flag` tinyint(1) NULL DEFAULT NULL COMMENT '删除状态(YesOrNoEnum)',
  `init_flag` tinyint(1) NULL DEFAULT NULL COMMENT '初始状态(YesOrNoEnum)',
  `sort` int NULL DEFAULT NULL COMMENT '排序',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建者ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` bigint NULL DEFAULT NULL COMMENT '更新者ID',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `scope_user_id` bigint NULL DEFAULT NULL COMMENT '数据权限用户ID',
  `scope_org_id` bigint NULL DEFAULT NULL COMMENT '数据权限机构ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2080940369234329603 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '系统角色表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_role
-- ----------------------------

-- ----------------------------
-- Table structure for sys_role_menu_rel
-- ----------------------------
DROP TABLE IF EXISTS `sys_role_menu_rel`;
CREATE TABLE `sys_role_menu_rel`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '角色菜单关联表自增ID',
  `role_id` bigint NOT NULL COMMENT '角色ID',
  `root_menu_id` bigint NOT NULL COMMENT '根菜单ID',
  `menu_id` bigint NOT NULL COMMENT '菜单ID',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `ROLE_ID&MENU_ID`(`role_id` ASC, `menu_id` ASC) USING BTREE COMMENT '角色和菜单',
  INDEX `ROLE_ID`(`role_id` ASC) USING BTREE COMMENT '角色ID',
  INDEX `MENU_ID`(`menu_id` ASC) USING BTREE COMMENT '菜单ID'
) ENGINE = InnoDB AUTO_INCREMENT = 2096853278426574854 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '角色菜单关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_role_menu_rel
-- ----------------------------

-- ----------------------------
-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user`  (
  `user_id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `nick_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户昵称',
  `avatar` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '头像地址',
  `phone` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号码',
  `id_card` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证唯一编号',
  `gender` tinyint(1) NULL DEFAULT NULL COMMENT '用户性别（UserSexEnum）',
  `admin_flag` tinyint(1) NULL DEFAULT NULL COMMENT '管理员状态(AdminFlagEnum)',
  `user_flag` tinyint(1) NULL DEFAULT NULL COMMENT '帐号状态（UserFlagEnum）',
  `del_flag` tinyint(1) NULL DEFAULT 0 COMMENT '删除标志（YesOrNoEnum）',
  `login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后登陆IP',
  `login_date` datetime NULL DEFAULT NULL COMMENT '最后登陆时间',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建者ID',
  `create_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` bigint NULL DEFAULT NULL COMMENT '更新者ID',
  `update_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2093154638617075715 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统用户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_user
-- ----------------------------

-- ----------------------------
-- Table structure for sys_user_role_rel
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_role_rel`;
CREATE TABLE `sys_user_role_rel`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `role_id` bigint NULL DEFAULT NULL COMMENT '角色ID',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户ID',
  `init_flag` int NULL DEFAULT NULL COMMENT '初始化标识',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `user&role`(`role_id` ASC, `user_id` ASC) USING BTREE COMMENT '人员角色联合索引',
  INDEX `USER_ID`(`user_id` ASC) USING BTREE COMMENT '人员ID',
  INDEX `ROLE_ID`(`role_id` ASC) USING BTREE COMMENT '角色ID'
) ENGINE = InnoDB AUTO_INCREMENT = 2093154639787286529 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '用户角色关系表' ROW_FORMAT = DYNAMIC;

